const KG_SOURCE=window.KG_DATA||{directory:[],topicMetrics:{},relations:[],metricInfo:{},meta:{}};
const KG_LEVEL_NAMES={1:'责任中心',2:'业务域',3:'对象',4:'主题'};
const KG_LEVEL_FIELDS={1:'责任中心',2:'业务域',3:'对象',4:'主题'};
function kgUnique(values){return [...new Set(values.filter(Boolean))]}
function kgMetrics(topic){return KG_SOURCE.topicMetrics[topic]||[]}
function kgKey(level,parts){return `${level}:${parts.join('/')}`}
function kgScope(){return state.graphScope||{level:4,parts:['区域TOB','政企','渠道','伙伴激励']}}
function kgScopeActive(level,parts){const scope=kgScope();return scope.level===level&&scope.parts.join('/')===parts.join('/')}
function kgRowsForParts(parts){return KG_SOURCE.directory.filter(row=>parts.every((value,i)=>row[KG_LEVEL_FIELDS[i+1]]===value))}
function kgChildValues(rows,level){return kgUnique(rows.map(row=>row[KG_LEVEL_FIELDS[level]]))}
function kgTreeBranch(label,level,parts,rows,content){const key=kgKey(level,parts),open=state.graphExpanded?.has(key);return `<div class='kg-tree-branch level-${level}'><div class='kg-tree-row ${kgScopeActive(level,parts)?'active':''}'><button class='kg-tree-toggle' type='button' data-kg-toggle='${esc(key)}' aria-label='${open?'收起':'展开'}${esc(label)}' aria-expanded='${open}'>${open?'−':'+'}</button><button class='kg-tree-scope' type='button' data-kg-scope-level='${level}' data-kg-scope-parts='${esc(JSON.stringify(parts))}'><span class='kg-level'>L${level}</span><span class='kg-tree-label'>${esc(label)}</span><small>${level===3?kgChildValues(rows,4).length:rows.length}</small></button></div><div class='kg-tree-children' ${open?'':'hidden'}>${content}</div></div>`}
function kgDirectoryTree(){const rows=KG_SOURCE.directory;return kgChildValues(rows,1).map(l1=>{const r1=rows.filter(x=>x['责任中心']===l1),p1=[l1];const c1=kgChildValues(r1,2).map(l2=>{const r2=r1.filter(x=>x['业务域']===l2),p2=[l1,l2];const c2=kgChildValues(r2,3).map(l3=>{const r3=r2.filter(x=>x['对象']===l3),p3=[l1,l2,l3];const topics=kgChildValues(r3,4).map(topic=>{const p4=[l1,l2,l3,topic];return `<button type='button' class='kg-topic ${kgScopeActive(4,p4)?'active':''}' data-kg-scope-level='4' data-kg-scope-parts='${esc(JSON.stringify(p4))}'><span class='kg-topic-dot'></span><span>${esc(topic)}</span><small>${kgMetrics(topic).length}</small></button>`}).join('');return kgTreeBranch(l3,3,p3,r3,topics)}).join('');return kgTreeBranch(l2,2,p2,r2,c2)}).join('');return kgTreeBranch(l1,1,p1,r1,c1)}).join('')}
function kgTruncate(name,max=16){return name.length>max?name.slice(0,max-1)+'…':name}
function kgNodeLines(name,max=11){if(name.length<=max)return [name];return [name.slice(0,max-1),kgTruncate(name.slice(max-1),max)]}
function kgScopeMeta(){const scope=kgScope(),rows=kgRowsForParts(scope.parts),label=scope.parts[scope.level-1]||'',topics=kgChildValues(rows,4),topicMetrics=Object.fromEntries(topics.map(topic=>[topic,kgMetrics(topic)])),metrics=kgUnique(Object.values(topicMetrics).flat()),relations=KG_SOURCE.relations.filter(x=>metrics.includes(x.source)||metrics.includes(x.target)),external=kgUnique(relations.flatMap(x=>[x.source,x.target]).filter(x=>!metrics.includes(x)));return {scope,rows,label,topics,topicMetrics,metrics,relations,external,path:scope.parts.join(' / '),type:KG_LEVEL_NAMES[scope.level]}}
function kgNodeRadius(type){return type==='root'?52:type==='topic'?42:type==='domain'||type==='object'?46:34}
function kgPolar(cx,cy,r,angle){return {x:cx+Math.cos(angle)*r,y:cy+Math.sin(angle)*r}}
function kgMetricNode(name,p,index,external=false){const selected=name===state.selectedGraphMetric,related=KG_SOURCE.relations.some(x=>x.source===name||x.target===name),lines=kgNodeLines(name,7);return `<g class='kg-node ${selected?'selected':''} ${related?'related':''} ${external?'external':''}' style='--i:${index}' role='button' tabindex='0' aria-label='查看指标 ${esc(name)}${external?'，跨主题关联指标':''}' data-metric-node='${esc(name)}' transform='translate(${p.x.toFixed(1)} ${p.y.toFixed(1)})'><title>${esc(name)}${external?'（跨主题关联）':''}</title><circle class='kg-node-halo' r='39'/><circle class='kg-node-shell' r='34'/><circle class='kg-node-dot' cx='0' cy='-25' r='3'/><text class='kg-node-kind' text-anchor='middle' y='-15'>${external?'关联指标':'指标'}</text><text class='kg-node-name' text-anchor='middle' y='${lines.length===1?6:1}'>${esc(lines[0])}</text>${lines[1]?`<text class='kg-node-name sub' text-anchor='middle' y='12'>${esc(lines[1])}</text>`:''}</g>`}
function kgDirectoryNode(label,type,p,index,attrs='',variant='topic'){const radius=kgNodeRadius(variant),lines=kgNodeLines(label,variant==='root'?8:6),interactive=attrs?`role='button' tabindex='0' ${attrs}`:`role='img' aria-label='当前${esc(type)} ${esc(label)}'`;return `<g class='kg-dir-node ${variant}' style='--i:${index}' ${interactive} transform='translate(${p.x.toFixed(1)} ${p.y.toFixed(1)})'><circle class='kg-dir-halo' r='${radius+6}'/><circle class='kg-dir-shell' r='${radius}'/><text class='kg-dir-type' text-anchor='middle' y='-10'>${esc(type)}</text><text class='kg-dir-name' text-anchor='middle' y='${lines.length===1?8:4}'>${esc(lines[0])}</text>${lines[1]?`<text class='kg-dir-name sub' text-anchor='middle' y='16'>${esc(lines[1])}</text>`:''}</g>`}
function kgEdge(path,kind='directory',index=0,arrow=false){return `<path class='kg-edge ${kind}-edge' style='--i:${index}' ${arrow?`marker-end='url(#kg-arrow)'`:''} d='${path}'/>`}
function kgSimpleLevelGraph(meta){const nextLevel=meta.scope.level+1,values=kgChildValues(meta.rows,nextLevel),width=900,height=540,cx=450,cy=270,ring=values.length===1?190:185;let edges='',nodes='';values.forEach((label,i)=>{const angle=-Math.PI/2+(Math.PI*2*i/Math.max(values.length,1)),p=kgPolar(cx,cy,ring,angle),parts=[...meta.scope.parts,label],attrs=`data-kg-scope-level='${nextLevel}' data-kg-scope-parts='${esc(JSON.stringify(parts))}' aria-label='查看${KG_LEVEL_NAMES[nextLevel]} ${esc(label)}'`;edges+=kgEdge(`M ${cx} ${cy} L ${p.x.toFixed(1)} ${p.y.toFixed(1)}`,'directory',i);nodes+=kgDirectoryNode(label,KG_LEVEL_NAMES[nextLevel],p,i,attrs,nextLevel===3?'object':'domain')});return {width,height,body:edges+kgDirectoryNode(meta.label,meta.type,{x:cx,y:cy},0,'','root')+nodes,description:`${meta.type}${meta.label}以辐射布局连接 ${values.length} 个${KG_LEVEL_NAMES[nextLevel]}节点。`}}
function kgTopicGraph(meta){const base=kgMetrics(meta.label),relations=KG_SOURCE.relations.filter(x=>base.includes(x.source)||base.includes(x.target)),external=kgUnique(relations.flatMap(x=>[x.source,x.target]).filter(x=>!base.includes(x))),metrics=[...base,...external],size=metrics.length>30?1080:metrics.length>16?900:760,c=size/2,positions={},rings=metrics.length>30?[{n:12,r:185},{n:18,r:310},{n:99,r:435}]:metrics.length>16?[{n:10,r:175},{n:99,r:330}]:[{n:99,r:230}];let cursor=0;for(const ring of rings){const names=metrics.slice(cursor,cursor+ring.n);names.forEach((name,i)=>{const offset=(cursor%2)*0.11,angle=-Math.PI/2+offset+Math.PI*2*i/Math.max(names.length,1);positions[name]=kgPolar(c,c,ring.r,angle)});cursor+=names.length;if(cursor>=metrics.length)break}let edges=base.map((name,i)=>kgEdge(`M ${c} ${c} L ${positions[name].x.toFixed(1)} ${positions[name].y.toFixed(1)}`,'theme',i)).join('');edges+=relations.map((r,i)=>{const a=positions[r.source],b=positions[r.target];if(!a||!b)return '';const mx=(a.x+b.x)/2,my=(a.y+b.y)/2-28;return kgEdge(`M ${a.x.toFixed(1)} ${a.y.toFixed(1)} Q ${mx.toFixed(1)} ${my.toFixed(1)} ${b.x.toFixed(1)} ${b.y.toFixed(1)}`,'metric',i,true)}).join('');const nodes=metrics.map((name,i)=>kgMetricNode(name,positions[name],i,external.includes(name))).join('');return {width:size,height:size,body:edges+kgDirectoryNode(meta.label,'主题',{x:c,y:c},0,'','root')+nodes,description:`主题${meta.label}以辐射布局展示 ${base.length} 个指标、${external.length} 个跨主题关联指标与 ${relations.length} 条指标关系。`}}
function kgForceLayout(nodes,links,width,height){const byId=Object.fromEntries(nodes.map(n=>[n.id,n])),cx=width/2,cy=height/2,topics=nodes.filter(n=>n.type==='topic');nodes.forEach((n,i)=>{n.vx=0;n.vy=0;if(n.type==='root'){n.x=cx;n.y=cy;return}if(n.type==='topic'){const ti=topics.indexOf(n),p=kgPolar(cx,cy,250,-Math.PI/2+Math.PI*2*ti/Math.max(topics.length,1));n.x=p.x;n.y=p.y;return}const parents=links.filter(l=>l.target===n.id&&byId[l.source]?.type==='topic'),parent=byId[parents[0]?.source],mi=i+1,angle=Math.atan2((parent?.y||cy)-cy,(parent?.x||cx)-cx)+(mi%9-4)*.12,r=390+Math.floor((mi%27)/9)*88;n.x=cx+Math.cos(angle)*r;n.y=cy+Math.sin(angle)*r});for(let step=0;step<170;step++){nodes.forEach(n=>{n.fx=(cx-n.x)*.0009;n.fy=(cy-n.y)*.0009});for(let i=0;i<nodes.length;i++)for(let j=i+1;j<nodes.length;j++){const a=nodes[i],b=nodes[j],dx=b.x-a.x||.01,dy=b.y-a.y||.01,d2=Math.max(64,dx*dx+dy*dy),d=Math.sqrt(d2),min=kgNodeRadius(a.type)+kgNodeRadius(b.type)+14,force=d<min?(min-d)*.055:Math.min(.7,1000/d2),ux=dx/d,uy=dy/d;a.fx-=ux*force;a.fy-=uy*force;b.fx+=ux*force;b.fy+=uy*force}links.forEach(l=>{const a=byId[l.source],b=byId[l.target];if(!a||!b)return;const dx=b.x-a.x,dy=b.y-a.y,d=Math.max(1,Math.sqrt(dx*dx+dy*dy)),target=l.kind==='directory'?235:l.kind==='theme'?118:175,k=l.kind==='metric'?.008:.018,pull=(d-target)*k,ux=dx/d,uy=dy/d;if(a.type!=='root'){a.fx+=ux*pull;a.fy+=uy*pull}b.fx-=ux*pull;b.fy-=uy*pull});nodes.forEach(n=>{if(n.type==='root'){n.x=cx;n.y=cy;return}n.vx=(n.vx+n.fx)*.76;n.vy=(n.vy+n.fy)*.76;const speed=Math.max(1,Math.sqrt(n.vx*n.vx+n.vy*n.vy)),cap=7;n.x+=n.vx*Math.min(1,cap/speed);n.y+=n.vy*Math.min(1,cap/speed);const pad=kgNodeRadius(n.type)+22;n.x=Math.max(pad,Math.min(width-pad,n.x));n.y=Math.max(pad,Math.min(height-pad,n.y))})}return byId}
function kgObjectGraph(meta){const width=1400,height=1180,nodes=[{id:'root',type:'root',label:meta.label}],links=[],metricNames=kgUnique(meta.metrics),topicIds={};meta.topics.forEach((topic,ti)=>{const id=`t:${topic}`;topicIds[topic]=id;nodes.push({id,type:'topic',label:topic,index:ti});links.push({source:'root',target:id,kind:'directory',index:ti});meta.topicMetrics[topic].forEach(metric=>links.push({source:id,target:`m:${metric}`,kind:'theme'}))});metricNames.forEach((name,i)=>nodes.push({id:`m:${name}`,type:'metric',label:name,index:i}));meta.relations.forEach((r,i)=>links.push({source:`m:${r.source}`,target:`m:${r.target}`,kind:'metric',index:i}));const pos=kgForceLayout(nodes,links,width,height);let edges='';links.forEach((l,i)=>{const a=pos[l.source],b=pos[l.target];if(!a||!b)return;const curve=l.kind==='metric'?22:0,path=curve?`M ${a.x.toFixed(1)} ${a.y.toFixed(1)} Q ${((a.x+b.x)/2).toFixed(1)} ${((a.y+b.y)/2-curve).toFixed(1)} ${b.x.toFixed(1)} ${b.y.toFixed(1)}`:`M ${a.x.toFixed(1)} ${a.y.toFixed(1)} L ${b.x.toFixed(1)} ${b.y.toFixed(1)}`;edges+=kgEdge(path,l.kind,i,l.kind==='metric')});const topicNodes=meta.topics.map((topic,ti)=>{const parts=[...meta.scope.parts,topic],attrs=`data-kg-scope-level='4' data-kg-scope-parts='${esc(JSON.stringify(parts))}' aria-label='聚焦主题 ${esc(topic)}'`;return kgDirectoryNode(topic,'主题',pos[topicIds[topic]],ti,attrs,'topic')}).join('');const metricNodes=metricNames.map((name,i)=>kgMetricNode(name,pos[`m:${name}`],i)).join('');return {width,height,body:edges+kgDirectoryNode(meta.label,'对象',pos.root,0,'','root')+topicNodes+metricNodes,description:`对象${meta.label}以力导向布局展示 ${meta.topics.length} 个主题、${meta.metrics.length} 个指标和 ${meta.relations.length} 条指标关系。`}}
function kgGraphSvg(meta){let graph=meta.scope.level<3?kgSimpleLevelGraph(meta):meta.scope.level===3?kgObjectGraph(meta):kgTopicGraph(meta);return `<svg class='kg-svg dynamic' style='width:${graph.width}px;min-width:${Math.min(graph.width,760)}px' viewBox='0 0 ${graph.width} ${graph.height}' role='img' aria-labelledby='kg-graph-title kg-graph-desc'><title id='kg-graph-title'>${esc(meta.label)}知识图谱</title><desc id='kg-graph-desc'>${esc(graph.description)}点击目录节点继续钻取，点击指标查看详细信息。</desc><defs><marker id='kg-arrow' viewBox='0 0 10 10' refX='8' refY='5' markerWidth='6' markerHeight='6' orient='auto-start-reverse'><path d='M 0 0 L 10 5 L 0 10 z'/></marker></defs>${graph.body}</svg>`}
function kgCyModel(meta){const elements=[],nodeIds=new Map();let edgeIndex=0;const addNode=(key,label,kind,extra={})=>{const id=`n${nodeIds.size}`;nodeIds.set(key,id);elements.push({group:'nodes',data:{id,label,kind,...extra},classes:[kind,extra.external?'external':'',extra.selected?'selected':'',extra.related?'related':''].filter(Boolean).join(' ')});return id};const addEdge=(source,target,kind)=>{if(!source||!target)return;elements.push({group:'edges',data:{id:`e${edgeIndex++}`,source,target,kind},classes:kind})};const root=addNode('root',meta.label,'root',{nodeType:meta.type});if(meta.scope.level<3){const next=meta.scope.level+1;kgChildValues(meta.rows,next).forEach(label=>{const parts=[...meta.scope.parts,label],id=addNode(`scope:${parts.join('/')}`,label,next===3?'object':'domain',{scopeLevel:next,scopeParts:JSON.stringify(parts),nodeType:KG_LEVEL_NAMES[next]});addEdge(root,id,'directory')})}else if(meta.scope.level===3){meta.topics.forEach(topic=>{const parts=[...meta.scope.parts,topic],id=addNode(`topic:${topic}`,topic,'topic',{scopeLevel:4,scopeParts:JSON.stringify(parts),nodeType:'主题'});addEdge(root,id,'directory')});meta.metrics.forEach(name=>addNode(`metric:${name}`,name,'metric',{metricName:name,nodeType:'指标',selected:name===state.selectedGraphMetric,related:KG_SOURCE.relations.some(x=>x.source===name||x.target===name)}));meta.topics.forEach(topic=>meta.topicMetrics[topic].forEach(name=>addEdge(nodeIds.get(`topic:${topic}`),nodeIds.get(`metric:${name}`),'theme')));meta.relations.forEach(x=>addEdge(nodeIds.get(`metric:${x.source}`),nodeIds.get(`metric:${x.target}`),'relation'))}else{const base=kgMetrics(meta.label),all=[...base,...meta.external];all.forEach(name=>addNode(`metric:${name}`,name,'metric',{metricName:name,nodeType:meta.external.includes(name)?'跨主题指标':'指标',external:meta.external.includes(name),selected:name===state.selectedGraphMetric,related:KG_SOURCE.relations.some(x=>x.source===name||x.target===name)}));base.forEach(name=>addEdge(root,nodeIds.get(`metric:${name}`),'theme'));meta.relations.forEach(x=>addEdge(nodeIds.get(`metric:${x.source}`),nodeIds.get(`metric:${x.target}`),'relation'))}return elements}
function kgGraphCanvas(meta){return `<div class='kg-canvas kg-cy-shell'><div class='kg-graph-toolbar' aria-label='图谱视图控制'><button type='button' data-kg-zoom='in' aria-label='放大图谱'>＋</button><button type='button' data-kg-zoom='out' aria-label='缩小图谱'>−</button><button type='button' data-kg-zoom='fit' aria-label='适应画布'>适应</button></div><div id='kg-cy' class='kg-cy' role='application' aria-label='${esc(meta.label)}知识图谱，可拖拽节点、滚轮缩放和平移画布'></div><p class='sr-only'>图谱提供可缩放的可视化视图，完整关系同时列于下方关系清单。</p></div>`}
function kgSelectMetric(name,cy){state.selectedGraphMetric=name;cy.nodes().removeClass('selected');const node=cy.nodes().filter(n=>n.data('metricName')===name);node.addClass('selected');const details=document.querySelector('.kg-details-body');if(details)details.innerHTML=kgDetails(kgScopeMeta());document.querySelectorAll('.kg-details-body [data-metric-node]').forEach(button=>button.onclick=()=>kgSelectMetric(button.dataset.metricNode,cy))}
function initKnowledgeGraph(){const container=document.getElementById('kg-cy');if(!container)return;if(window.kgCy)window.kgCy.destroy();if(typeof cytoscape!=='function'){container.innerHTML=`<div class='kg-empty'><h3>图谱组件加载失败</h3><p>请刷新页面后重试。</p></div>`;return}const meta=kgScopeMeta(),force=meta.scope.level===3,cy=cytoscape({container,elements:kgCyModel(meta),minZoom:.28,maxZoom:2.8,boxSelectionEnabled:false,autoungrabify:false,style:[{selector:'node',style:{'width':64,'height':64,'background-color':'#fff','border-width':2,'border-color':'#9eb1c8','label':'data(label)','font-family':'Inter, PingFang SC, Microsoft YaHei, sans-serif','font-size':9,'font-weight':600,'color':'#27394f','text-wrap':'wrap','text-max-width':52,'text-valign':'center','text-halign':'center','overlay-opacity':0,'transition-property':'background-color,border-color,border-width,overlay-opacity','transition-duration':'160ms'}},{selector:'node.root',style:{'width':96,'height':96,'background-color':'#173f7d','border-width':5,'border-color':'#d7e6fb','color':'#fff','font-size':13,'font-weight':700,'text-max-width':74}},{selector:'node.topic',style:{'width':78,'height':78,'background-color':'#eaf3ff','border-color':'#4f86ce','font-size':10,'font-weight':700,'text-max-width':62}},{selector:'node.domain,node.object',style:{'width':82,'height':82,'background-color':'#e6f0ff','border-color':'#557fb7','font-size':11,'font-weight':700,'text-max-width':64}},{selector:'node.related',style:{'background-color':'#fff7e8','border-color':'#d68a2f'}},{selector:'node.external',style:{'border-style':'dashed','border-color':'#c97920'}},{selector:'node:selected,node.selected',style:{'background-color':'#2563eb','border-color':'#b9d3ff','border-width':6,'color':'#fff','overlay-color':'#2563eb','overlay-opacity':.1,'overlay-padding':8}},{selector:'node:active',style:{'overlay-color':'#2563eb','overlay-opacity':.13,'overlay-padding':10}},{selector:'edge',style:{'width':1.25,'curve-style':'bezier','line-color':'#b7c7d9','opacity':.72}},{selector:'edge.directory',style:{'width':1.8,'line-color':'#6d8eb7','line-style':'dashed'}},{selector:'edge.theme',style:{'line-color':'#aec2d9'}},{selector:'edge.relation',style:{'width':2.2,'line-color':'#d67c16','target-arrow-color':'#d67c16','target-arrow-shape':'triangle','arrow-scale':.8,'line-style':'dashed','opacity':.95}}],layout:force?{name:'cose',animate:'end',animationDuration:850,fit:true,padding:72,randomize:true,nodeRepulsion:node=>node.data('kind')==='root'?1200000:850000,idealEdgeLength:edge=>edge.hasClass('relation')?180:edge.hasClass('directory')?190:115,edgeElasticity:.12,nestingFactor:1.2,gravity:.18,numIter:750,initialTemp:180,coolingFactor:.96,minTemp:1}:{name:'concentric',animate:true,animationDuration:620,fit:true,padding:76,startAngle:-Math.PI/2,sweep:Math.PI*2,clockwise:true,equidistant:false,minNodeSpacing:54,concentric:node=>node.data('kind')==='root'?100:node.data('kind')==='topic'||node.data('kind')==='domain'||node.data('kind')==='object'?60:10,levelWidth:()=>35}});window.kgCy=cy;container.dataset.nodeCount=String(cy.nodes().length);container.dataset.edgeCount=String(cy.edges().length);container.dataset.layout=force?'cose':'concentric';cy.on('tap','node',event=>{const node=event.target,metric=node.data('metricName'),level=node.data('scopeLevel');if(metric){kgSelectMetric(metric,cy);return}if(level){state.graphScope={level:+level,parts:JSON.parse(node.data('scopeParts'))};state.selectedGraphTopic=state.graphScope.parts[3]||'';state.selectedGraphMetric='';render()}});cy.on('mouseover','node',()=>container.style.cursor='pointer');cy.on('mouseout','node',()=>container.style.cursor='grab');document.querySelectorAll('[data-kg-zoom]').forEach(button=>button.onclick=()=>{const action=button.dataset.kgZoom;if(action==='fit')cy.animate({fit:{eles:cy.elements(),padding:72},duration:260});else cy.animate({zoom:{level:cy.zoom()*(action==='in'?1.22:.82),renderedPosition:{x:container.clientWidth/2,y:container.clientHeight/2}},duration:180})});cy.one('layoutstop',()=>cy.fit(undefined,72))}
function kgG6NodeStyle(kind,extra={}){const shared={cursor:extra.scopeLevel||extra.metricName?'pointer':'default',labelText:kgTruncate(extra.label||'',13),labelPlacement:'center',labelWordWrap:true,labelMaxWidth:kind==='root'?82:kind==='topic'||kind==='object'||kind==='domain'?68:54,labelFontFamily:'Inter, PingFang SC, Microsoft YaHei, sans-serif',labelFontWeight:700,shadowBlur:kind==='root'?26:14,shadowOffsetX:0,shadowOffsetY:5};if(kind==='root')return {...shared,size:106,fill:'#12385f',stroke:'#7dd3fc',lineWidth:3,labelFill:'#f8fbff',labelFontSize:13,shadowColor:'rgba(39,174,229,.32)'};if(kind==='topic'||kind==='object'||kind==='domain')return {...shared,size:kind==='topic'?80:88,fill:'#17486c',stroke:'#5bb9dd',lineWidth:2,labelFill:'#edf9ff',labelFontSize:10,shadowColor:'rgba(18,72,108,.32)'};if(extra.external)return {...shared,size:68,fill:'#3d311d',stroke:'#e0b35b',lineWidth:2,lineDash:[5,4],labelFill:'#fff3cd',labelFontSize:9,shadowColor:'rgba(224,179,91,.2)'};if(extra.related)return {...shared,size:68,fill:'#f5ddb0',stroke:'#d6a64d',lineWidth:2,labelFill:'#302612',labelFontSize:9,shadowColor:'rgba(214,166,77,.2)'};return {...shared,size:66,fill:'#eaf1f6',stroke:'#86a8bf',lineWidth:1.6,labelFill:'#193047',labelFontSize:9,shadowColor:'rgba(5,20,36,.28)'}}
function kgG6EdgeStyle(kind){if(kind==='relation')return {stroke:'#e6b85d',lineWidth:1.8,lineDash:[7,5],opacity:.88,endArrow:true,endArrowType:'triangle',endArrowSize:6};if(kind==='directory')return {stroke:'#48b7df',lineWidth:1.7,lineDash:[4,5],opacity:.65};return {stroke:'#6f91aa',lineWidth:1.2,opacity:.48}}
function kgG6Model(meta){const nodes=[],edges=[],nodeIds=new Map();let edgeIndex=0;const addNode=(key,label,kind,extra={})=>{const id='n'+nodeIds.size,data={label,kind,...extra};nodeIds.set(key,id);nodes.push({id,data,style:kgG6NodeStyle(kind,{...data,label}),states:extra.selected?['selected']:[]});return id};const addEdge=(source,target,kind)=>{if(!source||!target)return;edges.push({id:'e'+edgeIndex++,source,target,data:{kind},style:kgG6EdgeStyle(kind)})};const root=addNode('root',meta.label,'root',{nodeType:meta.type});if(meta.scope.level<3){const next=meta.scope.level+1;kgChildValues(meta.rows,next).forEach(label=>{const parts=[...meta.scope.parts,label],id=addNode('scope:'+parts.join('/'),label,next===3?'object':'domain',{scopeLevel:next,scopeParts:JSON.stringify(parts),nodeType:KG_LEVEL_NAMES[next]});addEdge(root,id,'directory')})}else if(meta.scope.level===3){meta.topics.forEach(topic=>{const parts=[...meta.scope.parts,topic],id=addNode('topic:'+topic,topic,'topic',{scopeLevel:4,scopeParts:JSON.stringify(parts),nodeType:'主题'});addEdge(root,id,'directory')});meta.metrics.forEach(name=>addNode('metric:'+name,name,'metric',{metricName:name,nodeType:'指标',selected:name===state.selectedGraphMetric,related:KG_SOURCE.relations.some(x=>x.source===name||x.target===name)}));meta.topics.forEach(topic=>meta.topicMetrics[topic].forEach(name=>addEdge(nodeIds.get('topic:'+topic),nodeIds.get('metric:'+name),'theme')));meta.relations.forEach(x=>addEdge(nodeIds.get('metric:'+x.source),nodeIds.get('metric:'+x.target),'relation'))}else{const base=kgMetrics(meta.label),all=[...base,...meta.external];all.forEach(name=>addNode('metric:'+name,name,'metric',{metricName:name,nodeType:meta.external.includes(name)?'跨主题指标':'指标',external:meta.external.includes(name),selected:name===state.selectedGraphMetric,related:KG_SOURCE.relations.some(x=>x.source===name||x.target===name)}));base.forEach(name=>addEdge(root,nodeIds.get('metric:'+name),'theme'));meta.relations.forEach(x=>addEdge(nodeIds.get('metric:'+x.source),nodeIds.get('metric:'+x.target),'relation'))}return {nodes,edges}}
function kgGraphCanvas(meta){return `<div class='kg-canvas kg-g6-shell'><div class='kg-stage-signature'><span><i></i>G6 LIVE GRAPH</span><small>拖拽节点 · 滚轮缩放 · 拖动画布</small></div><div class='kg-graph-toolbar' aria-label='图谱视图控制'><button type='button' data-kg-zoom='in' aria-label='放大图谱'>＋</button><button type='button' data-kg-zoom='out' aria-label='缩小图谱'>−</button><button type='button' data-kg-zoom='fit' aria-label='适应画布'>居中</button></div><div id='kg-cy' class='kg-cy' role='application' aria-label='${esc(meta.label)}知识图谱，可拖拽节点、滚轮缩放和平移画布'></div><p class='sr-only'>图谱提供可缩放的可视化视图，完整关系同时列于下方关系清单。</p></div>`}
function kgSelectMetric(name,graph,nodeId=''){state.selectedGraphMetric=name;if(graph&&nodeId){try{const selected=graph.getElementDataByState?.('node','selected')||[];selected.forEach(item=>graph.setElementState(item.id,[]));graph.setElementState(nodeId,['selected']);graph.focusElement?.(nodeId,{duration:280})}catch(error){console.warn('G6 selection update skipped',error)}}const details=document.querySelector('.kg-details-body');if(details)details.innerHTML=kgDetails(kgScopeMeta());document.querySelectorAll('.kg-details-body [data-metric-node]').forEach(button=>button.onclick=()=>{const item=(graph?.getNodeData?.()||[]).find(node=>node.data?.metricName===button.dataset.metricNode);kgSelectMetric(button.dataset.metricNode,graph,item?.id||'')})}
function initKnowledgeGraph(){const container=document.getElementById('kg-cy');if(!container)return;if(window.kgGraph){window.kgGraph.destroy();window.kgGraph=null}if(!window.G6?.Graph){container.innerHTML=`<div class='kg-empty'><h3>图谱组件加载失败</h3><p>请刷新页面后重试。</p></div>`;return}const meta=kgScopeMeta(),force=meta.scope.level===3,data=kgG6Model(meta);const graph=new G6.Graph({container,data,autoFit:{type:'view',options:{when:'always',direction:'both'}},animation:true,node:{type:'circle',style:d=>d.style,state:{selected:{fill:'#0d88b7',stroke:'#a9ebff',lineWidth:4,labelFill:'#fff',shadowColor:'rgba(55,205,255,.48)',shadowBlur:28}}},edge:{type:'line',style:d=>d.style,state:{highlight:{stroke:'#f2c66d',lineWidth:2.5,opacity:1}}},layout:force?{type:'d3-force',preventOverlap:true,link:{distance:145,strength:.62},manyBody:{strength:-720},center:{strength:.035},animation:true}:{type:'concentric',preventOverlap:true,nodeSpacing:42,sortBy:'kind',animation:true},behaviors:force?['drag-canvas','zoom-canvas','click-select','drag-element-force']:['drag-canvas','zoom-canvas','click-select','drag-element']});window.kgGraph=graph;container.dataset.nodeCount=String(data.nodes.length);container.dataset.edgeCount=String(data.edges.length);container.dataset.layout=force?'d3-force':'concentric';graph.on(G6.NodeEvent.CLICK,event=>{const datum=graph.getNodeData(event.target.id),info=datum?.data||{};if(info.metricName){kgSelectMetric(info.metricName,graph,event.target.id);return}if(info.scopeLevel){state.graphScope={level:+info.scopeLevel,parts:JSON.parse(info.scopeParts)};state.selectedGraphTopic=state.graphScope.parts[3]||'';state.selectedGraphMetric='';render()}});document.querySelectorAll('[data-kg-zoom]').forEach(button=>button.onclick=()=>{const action=button.dataset.kgZoom;if(action==='fit')graph.fitView({when:'always',direction:'both'},{duration:320});else graph.zoomBy(action==='in'?1.2:.84,{duration:180})});graph.render().then(()=>graph.fitView({when:'always',direction:'both'},{duration:520})).catch(error=>{console.error(error);container.innerHTML=`<div class='kg-empty'><h3>图谱渲染失败</h3><p>请刷新页面后重试。</p></div>`});document.querySelectorAll('.kg-details-body [data-metric-node]').forEach(button=>button.onclick=()=>{const item=data.nodes.find(node=>node.data?.metricName===button.dataset.metricNode);kgSelectMetric(button.dataset.metricNode,graph,item?.id||'')})}
function kgValue(value){return value&&String(value).trim()?String(value).trim():'—'}
function kgDetailRows(info){const groups=[['基础信息',['指标来源','指标是否已注册','分析视角']],['分析定义',['分析维度','分析度量','分析方法','下钻路径']],['规则与策略',['指标规则','策略大类','策略子类','策略内容','策略用途']]];return groups.map(([title,fields])=>`<section class='kg-detail-group'><h4>${title}</h4>${fields.map(field=>`<div class='kg-detail-row'><small>${field}</small><p class='${field==='指标规则'||field==='策略内容'?'pre':''}'>${esc(kgValue(info[field]))}</p></div>`).join('')}</section>`).join('')}
function kgDetails(meta){const metric=state.selectedGraphMetric,info=KG_SOURCE.metricInfo[metric]||{};if(!metric)return `<div class='kg-scope-detail'><span>${meta.type}节点</span><b>${esc(meta.label)}</b><p>${esc(meta.path)}</p><dl><div><dt>${meta.topics.length}</dt><dd>主题</dd></div><div><dt>${meta.metrics.length}</dt><dd>指标</dd></div><div><dt>${meta.relations.length}</dt><dd>指标关系</dd></div></dl><small>点击图谱中的目录节点继续钻取，或点击指标查看指标定义。</small></div>`;const links=KG_SOURCE.relations.filter(x=>x.source===metric||x.target===metric);return `<div class='kg-detail-head'><span>指标详情</span><b>${esc(metric)}</b><div><span class='status ${kgValue(info['指标是否已注册'])==='是'?'ok':'warn'}'>${kgValue(info['指标是否已注册'])==='是'?'已注册':'未注册'}</span><span class='kg-rel-count'>${links.length} 条指标关系</span></div></div>${kgDetailRows(info)}${links.length?`<section class='kg-detail-group'><h4>指标关系</h4><div class='kg-related-list'>${links.map(x=>{const incoming=x.target===metric,other=incoming?x.source:x.target;return `<button type='button' data-metric-node='${esc(other)}'><span>${incoming?'上游':'下游'}</span><b>${esc(other)}</b></button>`}).join('')}</div></section>`:''}`}
function kgAdjacency(meta){let rows=[];if(meta.scope.level<3){const next=meta.scope.level+1;kgChildValues(meta.rows,next).forEach(x=>rows.push([meta.type,meta.label,'包含',KG_LEVEL_NAMES[next],x]))}else if(meta.scope.level===3){meta.topics.forEach(topic=>{rows.push(['对象',meta.label,'包含主题','主题',topic]);meta.topicMetrics[topic].forEach(metric=>rows.push(['主题',topic,'包含指标','指标',metric]))});meta.relations.forEach(x=>rows.push(['指标',x.source,'关联指标','指标',x.target]))}else{meta.metrics.forEach(metric=>rows.push(['主题',meta.label,'包含指标','指标',metric]));meta.relations.forEach(x=>rows.push(['指标',x.source,'关联指标','指标',x.target]))}return `<details class='kg-adjacency'><summary><span>关系清单</span><small>无障碍替代视图 · ${rows.length} 条关系</small></summary><div class='table-wrap'><table class='data-table'><thead><tr><th>起点类型</th><th>起点</th><th>关系</th><th>终点类型</th><th>终点</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x[0])}</td><td>${esc(x[1])}</td><td>${esc(x[2])}</td><td>${esc(x[3])}</td><td>${x[3]==='指标'?`<button class='kg-table-link' data-metric-node='${esc(x[4])}'>${esc(x[4])}</button>`:esc(x[4])}</td></tr>`).join('')}</tbody></table></div></details>`}
function knowledgeGraphGovernance(stage){const isApproval=stage==='approval',meta=kgScopeMeta();if(!meta.metrics.includes(state.selectedGraphMetric)&&!meta.external.includes(state.selectedGraphMetric))state.selectedGraphMetric='';const action=isApproval?`<button class='btn' data-action='preview-evidence'>查看专家审核记录</button>`:'';return `${context()}${pageHead(`${isApproval?'STAGE 05 · 领域知识责任人':'STAGE 04 · 领域知识专家'}`,isApproval?'知识审批':'知识审核',isApproval?'按知识目录审阅动态图谱，核对目录、主题、指标定义与关系后提交认证。':'按知识目录逐层浏览动态图谱，核对目录、主题、指标定义与关系。',action)}<section class='kg-summary'><div><span>当前图谱范围 · ${meta.type}</span><b>${esc(meta.path)}</b></div><dl><div><dt>${meta.topics.length}</dt><dd>范围主题</dd></div><div><dt>${meta.metrics.length}</dt><dd>范围指标</dd></div><div><dt>${meta.relations.length}</dt><dd>指标关系</dd></div><div><dt>${KG_SOURCE.meta.uniqueMetrics||0}</dt><dd>全部指标</dd></div></dl></section><div class='kg-workbench'><aside class='panel kg-directory'><div class='panel-head'><div><h3>知识目录</h3><small>L1 责任中心 · L2 业务域 · L3 对象 · L4 主题</small></div></div><div class='kg-directory-body'>${kgDirectoryTree()}</div><footer><span>点击目录名称生成对应图谱</span><small>目录.xlsx · 主题到指标.xlsx</small></footer></aside><section class='panel kg-canvas-panel'><div class='panel-head'><div><h3>${esc(meta.label)}知识图谱</h3><small>${meta.type}节点 · ${meta.topics.length} 个主题 · ${meta.metrics.length} 个指标</small></div><div class='kg-legend'><span><i class='directory'></i>目录节点</span><span><i class='theme'></i>主题</span><span><i class='metric'></i>指标</span><span><i class='relation'></i>指标关系</span></div></div>${kgGraphCanvas(meta)}${kgAdjacency(meta)}</section><aside class='panel kg-details'><div class='panel-head'><div><h3>节点信息</h3><small>点击目录或指标节点查看</small></div></div><div class='kg-details-body'>${kgDetails(meta)}</div></aside></div>${isApproval?`<section class='panel kg-opinion'><div class='panel-head'><div><h3>审批意见</h3><small>审批意见将写入知识包版本与审计记录</small></div><span class='status ${state.approved?'ok':'warn'}'>${state.approved?'审批通过':'待填写'}</span></div><div class='panel-body'><div class='form-field'><label>领域知识责任人意见</label><textarea placeholder='请输入审批意见'>${state.approved?'审批通过：目录、主题与指标关系准确，可进入认证。':'目录层级清晰，主题与指标关系准确，建议通过审批。'}</textarea></div></div></section>`:''}<div class='action-bar'><span class='spacer'></span>${isApproval?`<button class='btn danger' data-action='reject-owner'>退回知识专家</button><button class='btn success' data-action='approve-owner'>审批通过并提交认证 →</button>`:`<button class='btn primary' data-action='submit-approval'>审核完成，提交知识审批 →</button>`}</div>`}
function reviewGraphPage(){return knowledgeGraphGovernance('review')}
function approvalGraphPage(){return knowledgeGraphGovernance('approval')}
